const petCards = await browserjs(tabId, () => {
  // Let's find all cards that contain a link to /pet/
  const links = Array.from(document.querySelectorAll('a[href*="/pet/"]'));
  return links.map(link => {
    // find card container
    let card = link;
    while (card.parentElement && !card.parentElement.classList.contains('grid') && card.parentElement.tagName !== 'MAIN' && card.parentElement.tagName !== 'BODY') {
      if (card.parentElement.children.length > 3) break;
      card = card.parentElement;
    }
    return {
      href: link.href,
      fullText: card.innerText.trim().replace(/\n+/g, ' -- ')
    };
  });
});

console.log("Total pet cards:", petCards.length);
// Check if any mention private owner or rehome or cared for by
const privateOwnerPets = petCards.filter(p => 
  p.fullText.toLowerCase().includes('private') || 
  p.fullText.toLowerCase().includes('owner') || 
  p.fullText.toLowerCase().includes('rehome') ||
  p.fullText.toLowerCase().includes('individual')
);
console.log("Matches:", JSON.stringify(privateOwnerPets, null, 2));

// Also let's print first 10 cards to see what text is on the cards
console.log("First 10 cards:", JSON.stringify(petCards.slice(0, 10), null, 2));

